def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Minimal scarcity-sharpened rule distilled from the best blind share-interface program.
    Weights: last round's returns plus a constant, raised to an exponent that falls from 1.75
    (empty pool) to 0.85 (full pool); the interface offers the whole pool in proportion to them."""
    fullness = np.clip(pool / cap, 0.0, 1.0)[:, None]
    return (prev_contrib + 10.0 / 3.0) ** (1.75 - 0.9 * fullness)

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Offer each agent an amount scaled by their remembered return rate."""
    p = prev_contrib.shape[1]
    if t == 1:
        mem['rate'] = np.full((pool.shape[0], p), 0.8)
    else:
        obs = np.where(prev_offer > 0.5, prev_contrib / np.maximum(prev_offer, 1e-12), mem['rate'])
        mem['rate'] = 0.7 * mem['rate'] + 0.3 * obs
    weight = np.clip(mem['rate'], 0.05, 1.0)
    share = weight / weight.sum(axis=1, keepdims=True)
    offer = pool[:, None] * share
    return np.maximum(offer, np.minimum(1.0, pool[:, None] / p))

