    p = prev_contrib.shape[1]
    if t == 1:
        mem['trust'] = np.full((pool.shape[0], p), 0.8)
    else:
        frac = np.where(prev_offer > 0, prev_contrib / np.maximum(prev_offer, 1e-12), mem['trust'])
        mem['trust'] = 0.7 * mem['trust'] + 0.3 * frac
    trust = np.clip(mem['trust'], 0.05, 1.0)
    share = trust / trust.sum(axis=1, keepdims=True)
    offers = pool[:, None] * share
    return np.minimum(offers, pool[:, None])

